let artSerial=0;
function artTone(hex,delta){const n=parseInt(hex.slice(1),16);return '#'+[16,8,0].map(shift=>Math.max(0,Math.min(255,((n>>shift)&255)+delta)).toString(16).padStart(2,'0')).join('')}
function artSVG(body,cls='piece',view='0 0 72 80'){
 // Local material lighting preserves silhouette readability at small tile sizes.
 let defs='';if(cls!=='ground-art'&&!cls.startsWith('ground-art ')){const prefix='mat'+(++artSerial),colors=[...new Set([...body.matchAll(/fill="(#[0-9a-fA-F]{6})"/g)].map(m=>m[1]))];colors.forEach((color,i)=>{const id=prefix+'-'+i;defs+=`<linearGradient id="${id}" x1="0" y1="0" x2=".8" y2="1"><stop stop-color="${artTone(color,17)}"/><stop offset=".48" stop-color="${color}"/><stop offset="1" stop-color="${artTone(color,-19)}"/></linearGradient>`;body=body.replaceAll('fill="'+color+'"','fill="url(#'+id+')"')})}
 return `<svg viewBox="${view}" class="${cls}" aria-hidden="true" xmlns="http://www.w3.org/2000/svg">${defs?'<defs>'+defs+'</defs>':''}${body}</svg>`
}
